using KennelPro.Interfaces.Reproduction; using KennelPro.Models.Reproduction; using KennelPro.Services.Dogs; using KennelPro.Validators;
namespace KennelPro.Services.Reproduction;
public class HeatCycleService { readonly IHeatCycleRepository _repo; readonly DogService _dogs; public HeatCycleService(IHeatCycleRepository repo, DogService dogs){_repo=repo;_dogs=dogs;} public async Task<List<HeatCycle>> GetForDogAsync(Guid dogId)=>await _dogs.GetDogForCurrentKennelAsync(dogId)==null?new(): (await _repo.GetByDogIdAsync(dogId)).ToList(); public async Task<HeatCycle?> GetByIdAsync(Guid id){var x=await _repo.GetByIdAsync(id);return x!=null&&await _dogs.GetDogForCurrentKennelAsync(x.DogId)!=null?x:null;} public async Task<(bool,string)> AddAsync(HeatCycle x){if(await _dogs.GetDogForCurrentKennelAsync(x.DogId)==null)return(false,"Dog not found.");x.Id=x.Id==Guid.Empty?Guid.NewGuid():x.Id;if(!HeatCycleValidator.Validate(x,out var e))return(false,e);await _repo.AddAsync(x);return(true,"");} public async Task<(bool,string)> UpdateAsync(HeatCycle x){var old=await GetByIdAsync(x.Id);if(old==null)return(false,"Cycle not found.");x.DogId=old.DogId;if(!HeatCycleValidator.Validate(x,out var e))return(false,e);await _repo.UpdateAsync(x);return(true,"");} public async Task<bool> DeleteAsync(Guid id){if(await GetByIdAsync(id)==null)return false;await _repo.DeleteAsync(id);return true;} }
